// GENERATED by scripts/ai/sketch/calibrate-pins.mjs — do not edit by hand.
// Re-run it after changing PIN_FRAME or a glyph in glyphs.ts.
//
// Where each class's pins sit, as fractions (u across, v down) of the drawn
// symbol's bounding box at pose 0. A symbol drawn bare and one drawn with leads
// both put their end pins on the edges of their bounding box, so one table
// serves both. A wire end is matched to the nearest of these.

import type { Wave1Class, Pose } from './classes'

export interface PinTemplate {
  /** A SimScript anchor name. */
  name: string
  u: number
  v: number
}

export const PIN_TEMPLATE: Record<Wave1Class, PinTemplate[]> = {
  'battery': [{ name: 'positive', u: 0, v: 0.5 }, { name: 'negative', u: 1, v: 0.5 }],
  'resistor': [{ name: 'a', u: 0, v: 0.5 }, { name: 'b', u: 1, v: 0.5 }],
  'capacitor': [{ name: 'a', u: 0, v: 0.5 }, { name: 'b', u: 1, v: 0.5 }],
  'inductor': [{ name: 'a', u: 0, v: 1 }, { name: 'b', u: 1, v: 1 }],
  'switch': [{ name: 'a', u: 0, v: 0.95 }, { name: 'b', u: 1, v: 0.95 }],
  'bulb': [{ name: 'a', u: 0, v: 0.5 }, { name: 'b', u: 1, v: 0.5 }],
  'led': [{ name: 'anode', u: 0, v: 0.651 }, { name: 'cathode', u: 1, v: 0.651 }],
  'diode': [{ name: 'anode', u: 0, v: 0.5 }, { name: 'cathode', u: 1, v: 0.5 }],
  'gnd': [{ name: 'terminal', u: 0.5, v: 0 }],
  'ac-source': [{ name: 'positive', u: 0, v: 0.5 }, { name: 'negative', u: 1, v: 0.5 }],
  'voltmeter': [{ name: 'a', u: 0, v: 0.5 }, { name: 'b', u: 1, v: 0.5 }],
  'ammeter': [{ name: 'a', u: 0, v: 0.5 }, { name: 'b', u: 1, v: 0.5 }],
  'and-gate': [{ name: 'input1', u: 0, v: 0.273 }, { name: 'input2', u: 0, v: 0.727 }, { name: 'output', u: 1, v: 0.5 }],
  'or-gate': [{ name: 'input1', u: 0, v: 0.273 }, { name: 'input2', u: 0, v: 0.727 }, { name: 'output', u: 1, v: 0.5 }],
  'xor-gate': [{ name: 'input1', u: 0, v: 0.273 }, { name: 'input2', u: 0, v: 0.727 }, { name: 'output', u: 1, v: 0.5 }],
  'nand-gate': [{ name: 'input1', u: 0, v: 0.273 }, { name: 'input2', u: 0, v: 0.727 }, { name: 'output', u: 1, v: 0.5 }],
  'nor-gate': [{ name: 'input1', u: 0, v: 0.273 }, { name: 'input2', u: 0, v: 0.727 }, { name: 'output', u: 1, v: 0.5 }],
  'not-gate': [{ name: 'input', u: 0, v: 0.5 }, { name: 'output', u: 1, v: 0.5 }],
  'bjt': [{ name: 'base', u: 0, v: 0.5 }, { name: 'collector', u: 0.915, v: 0 }, { name: 'emitter', u: 0.915, v: 1 }],
  'mosfet': [{ name: 'gate', u: 0, v: 0.633 }, { name: 'drain', u: 1, v: 0 }, { name: 'source', u: 1, v: 1 }],
  'opamp': [{ name: 'in-', u: 0, v: 0.269 }, { name: 'in+', u: 0, v: 0.731 }, { name: 'out', u: 1, v: 0.5 }],
}

/** A pose-0 box fraction after turning the drawing by `pose` (clockwise, y down). */
export function rotateUV(u: number, v: number, pose: Pose): [number, number] {
  switch (pose) {
    case 90: return [1 - v, u]
    case 180: return [1 - u, 1 - v]
    case 270: return [v, 1 - u]
    default: return [u, v]
  }
}

export interface WorldPin {
  name: string
  x: number
  y: number
}

/** Pin positions (page px) for a recognised symbol drawn inside `box`. [] for classes with no template. */
export function pinsOf(cls: string, pose: Pose, box: { x0: number; y0: number; x1: number; y1: number }): WorldPin[] {
  const tpl = PIN_TEMPLATE[cls as Wave1Class]
  if (!tpl) return []
  const w = box.x1 - box.x0
  const h = box.y1 - box.y0
  return tpl.map((p) => {
    const [u, v] = rotateUV(p.u, p.v, pose)
    return { name: p.name, x: box.x0 + u * w, y: box.y0 + v * h }
  })
}
